with matched_keys as (select product_id, id from order_items except select product_id, id from order_items where order_id in (11, 13, 33, 38)), verified as (select s.* from order_items s inner join matched_keys k on s.product_id = k.product_id and s.id = k.id) select product_id, sum(quantity) as total_quantity, bit_or(quantity) as quantity_bit_or, corr(unit_price, quantity) as corr_unit_price_quantity from verified group by 1
